-- SunSync. All energy is interval kWh, timestamps UTC, derived benefits are estimates.
-- UUIDs use PostgreSQL built-in gen_random_uuid(); no extension is required.
create table public.profiles(id uuid primary key references auth.users on delete cascade, full_name text not null default '' check(length(full_name)<=120), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.plans(id uuid primary key default gen_random_uuid(), name text not null unique, max_residents integer not null check(max_residents>0), monthly_price_inr numeric(12,2) not null default 0 check(monthly_price_inr>=0), active boolean not null default true, created_at timestamptz not null default now());
create table public.societies(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 160), address text not null default '', timezone text not null default 'Asia/Kolkata' check(timezone='Asia/Kolkata'), status text not null default 'active' check(status in ('active','suspended')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.role_assignments(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, role text not null check(role in ('resident','society','system')), society_id uuid references public.societies on delete cascade, created_at timestamptz not null default now(), check((role='system' and society_id is null) or (role<>'system' and society_id is not null)));
create unique index role_scope_unique on public.role_assignments(user_id,role,coalesce(society_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table public.registration_requests(id uuid primary key default gen_random_uuid(), applicant_id uuid not null references public.profiles, society_name text not null check(length(society_name) between 2 and 160), address text not null check(length(address) between 5 and 500), evidence text not null check(length(evidence) between 10 and 2000), status text not null default 'pending' check(status in ('pending','approved','rejected')), reviewed_by uuid references public.profiles, review_note text, society_id uuid references public.societies, created_at timestamptz not null default now(), reviewed_at timestamptz);
create unique index one_pending_application on public.registration_requests(applicant_id) where status='pending';
create table public.buildings(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, name text not null check(length(name) between 1 and 120), address text not null default '', created_at timestamptz not null default now(), unique(id,society_id), unique(society_id,name));
create table public.memberships(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, building_id uuid not null, user_id uuid not null references public.profiles, unit text not null check(length(unit) between 1 and 60), active boolean not null default true, created_at timestamptz not null default now(), foreign key(building_id,society_id) references public.buildings(id,society_id), unique(user_id,society_id), unique(building_id,unit), unique(id,society_id));
create table public.installations(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, building_id uuid, name text not null, capacity_kwp numeric(12,3) not null check(capacity_kwp>0 and capacity_kwp<=100000), commissioned_on date not null, active boolean not null default true, created_at timestamptz not null default now(), foreign key(building_id,society_id) references public.buildings(id,society_id), unique(id,society_id));
create table public.devices(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, installation_id uuid, membership_id uuid, serial text not null unique, kind text not null check(kind in ('generation','consumption')), active boolean not null default true, created_at timestamptz not null default now(), foreign key(installation_id,society_id) references public.installations(id,society_id), foreign key(membership_id,society_id) references public.memberships(id,society_id), check((kind='generation' and installation_id is not null and membership_id is null) or (kind='consumption' and membership_id is not null and installation_id is null)), unique(id,society_id));
create unique index one_active_generation_meter on public.devices(installation_id) where active and kind='generation';
create unique index one_active_consumption_meter on public.devices(membership_id) where active and kind='consumption';
create table public.readings(id uuid primary key default gen_random_uuid(), society_id uuid not null, device_id uuid not null, interval_start timestamptz not null, interval_end timestamptz not null, energy_kwh numeric(18,6) not null check(energy_kwh>=0 and energy_kwh<=1000000), source text not null check(length(source) between 3 and 300), source_record_id text not null check(length(source_record_id) between 1 and 200), verification text not null default 'operator_validated' check(verification in ('operator_validated','device_signed')), received_at timestamptz not null default now(), received_by uuid not null references public.profiles, revision integer not null default 1, correction_reason text, foreign key(device_id,society_id) references public.devices(id,society_id), check(interval_end>interval_start and interval_end<=interval_start+interval '1 day'), unique(device_id,interval_start,interval_end), unique(device_id,source_record_id));
create index readings_time on public.readings(society_id,interval_start);
create table public.reading_revisions(id bigint generated always as identity primary key, reading_id uuid not null references public.readings, previous_value numeric(18,6) not null, new_value numeric(18,6) not null, reason text not null, actor_id uuid not null references public.profiles, created_at timestamptz not null default now());
create table public.allocation_rules(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, method text not null default 'proportional_demand' check(method='proportional_demand'), description text not null default 'Allocate generation proportionally to measured eligible demand; never exceed consumption. Round down to 0.000001 kWh; residue remains unallocated.', created_at timestamptz not null default now(), unique(society_id));
create table public.tariffs(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, inr_per_kwh numeric(12,6) not null check(inr_per_kwh>=0 and inr_per_kwh<1000), valid_from timestamptz not null, valid_until timestamptz not null, source text not null check(length(source)>=10), approved_by uuid not null references public.profiles, created_at timestamptz not null default now(), check(valid_until>valid_from));
create table public.emission_factors(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, kg_co2e_per_kwh numeric(12,6) not null check(kg_co2e_per_kwh>=0 and kg_co2e_per_kwh<10), valid_from timestamptz not null, valid_until timestamptz not null, source text not null check(length(source)>=10), approved_by uuid not null references public.profiles, created_at timestamptz not null default now(), check(valid_until>valid_from));
create table public.allocation_batches(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, interval_start timestamptz not null, interval_end timestamptz not null, generation_kwh numeric(18,6) not null check(generation_kwh>=0), demand_kwh numeric(18,6) not null check(demand_kwh>=0), allocated_kwh numeric(18,6) not null check(allocated_kwh>=0 and allocated_kwh<=generation_kwh and allocated_kwh<=demand_kwh), rule_id uuid not null references public.allocation_rules, tariff_id uuid references public.tariffs, factor_id uuid references public.emission_factors, actor_id uuid not null references public.profiles, created_at timestamptz not null default now(), unique(society_id,interval_start,interval_end));
create table public.allocations(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, batch_id uuid not null references public.allocation_batches, membership_id uuid not null, energy_kwh numeric(18,6) not null check(energy_kwh>=0), estimated_savings_inr numeric(18,6), estimated_avoided_kg numeric(18,6), created_at timestamptz not null default now(), foreign key(membership_id,society_id) references public.memberships(id,society_id), unique(batch_id,membership_id));
create table public.credit_transactions(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, membership_id uuid not null, allocation_id uuid not null unique references public.allocations, amount_kwh numeric(18,6) not null check(amount_kwh>=0), created_at timestamptz not null default now(), foreign key(membership_id,society_id) references public.memberships(id,society_id));
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, society_id uuid references public.societies, title text not null, body text not null, read_at timestamptz, created_at timestamptz not null default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(), society_id uuid not null unique references public.societies, plan_id uuid not null references public.plans, status text not null check(status in ('active','paused','cancelled')), starts_at timestamptz not null default now(), ends_at timestamptz, created_at timestamptz not null default now());
create table public.platform_settings(key text primary key check(length(key)<=100), value jsonb not null, updated_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key, actor_id uuid references public.profiles, society_id uuid references public.societies, action text not null, entity_type text not null, entity_id text, details jsonb not null default '{}', created_at timestamptz not null default now());
create table public.rate_limits(actor_id uuid not null, operation text not null, bucket timestamptz not null, count integer not null, primary key(actor_id,operation,bucket));
create table public.community_challenges(id uuid primary key default gen_random_uuid(), society_id uuid not null references public.societies, title text not null, description text not null, target_kwh numeric(18,6) not null check(target_kwh>0), ends_at timestamptz not null, created_at timestamptz not null default now());
create index membership_user on public.memberships(user_id);
create index role_user on public.role_assignments(user_id);
create index notification_user on public.notifications(user_id,created_at desc);
create index allocation_membership on public.allocations(membership_id,created_at);
create index audit_time on public.audit_logs(created_at desc);
create function public.is_system() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.role_assignments where user_id=auth.uid() and role='system') $$;
create function public.admin_of(s uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.is_system() or exists(select 1 from public.role_assignments r join public.societies s2 on s2.id=r.society_id where r.user_id=auth.uid() and r.role='society' and r.society_id=s and s2.status='active') $$;
create function public.member_of(s uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships m join public.societies x on x.id=m.society_id where m.user_id=auth.uid() and m.society_id=s and m.active and x.status='active') $$;
create function public.owns_membership(m uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships where id=m and user_id=auth.uid() and active) $$;
create function public.new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),120)); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_user();
-- No role is ever read from user-controlled auth metadata.
do $$ declare t text; begin foreach t in array array['profiles','plans','societies','role_assignments','registration_requests','buildings','memberships','installations','devices','readings','reading_revisions','allocation_rules','tariffs','emission_factors','allocation_batches','allocations','credit_transactions','notifications','subscriptions','platform_settings','audit_logs','rate_limits','community_challenges'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
grant select on public.profiles,public.plans,public.societies,public.role_assignments,public.registration_requests,public.buildings,public.memberships,public.installations,public.devices,public.readings,public.reading_revisions,public.allocation_rules,public.tariffs,public.emission_factors,public.allocation_batches,public.allocations,public.credit_transactions,public.notifications,public.subscriptions,public.platform_settings,public.audit_logs,public.community_challenges to authenticated;
revoke all on public.rate_limits from authenticated;
grant update(full_name) on public.profiles to authenticated;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_system() or exists(select 1 from public.memberships m where m.user_id=profiles.id and public.admin_of(m.society_id)));
create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy roles_read on public.role_assignments for select to authenticated using(user_id=auth.uid() or public.is_system());
create policy society_read on public.societies for select to authenticated using(public.admin_of(id) or public.member_of(id));
grant update(name,address) on public.societies to authenticated;
create policy society_update on public.societies for update to authenticated using(public.admin_of(id)) with check(public.admin_of(id));
grant insert(applicant_id,society_name,address,evidence) on public.registration_requests to authenticated;
create policy request_insert on public.registration_requests for insert to authenticated with check(applicant_id=auth.uid() and status='pending' and reviewed_by is null and society_id is null);
create policy request_read on public.registration_requests for select to authenticated using(applicant_id=auth.uid() or public.is_system());
do $$ declare t text; begin foreach t in array array['buildings','installations','devices','allocation_rules','tariffs','emission_factors','community_challenges'] loop execute format('create policy scoped_read on public.%I for select to authenticated using(public.admin_of(society_id) or public.member_of(society_id))',t); execute format('grant insert,update on public.%I to authenticated',t); execute format('create policy scoped_insert on public.%I for insert to authenticated with check(public.admin_of(society_id))',t); execute format('create policy scoped_update on public.%I for update to authenticated using(public.admin_of(society_id)) with check(public.admin_of(society_id))',t); end loop; end $$;
-- Freeze provenance-bearing and historical configuration records: create a new version instead.
revoke update on public.tariffs, public.emission_factors, public.allocation_rules, public.devices from authenticated;
create policy membership_read on public.memberships for select to authenticated using(user_id=auth.uid() or public.admin_of(society_id));
create policy reading_read on public.readings for select to authenticated using(public.admin_of(society_id) or exists(select 1 from public.devices d where d.id=readings.device_id and public.owns_membership(d.membership_id)));
create policy revision_read on public.reading_revisions for select to authenticated using(exists(select 1 from public.readings r where r.id=reading_id));
create policy batch_read on public.allocation_batches for select to authenticated using(public.admin_of(society_id));
create policy allocation_read on public.allocations for select to authenticated using(public.admin_of(society_id) or public.owns_membership(membership_id));
create policy credit_read on public.credit_transactions for select to authenticated using(public.admin_of(society_id) or public.owns_membership(membership_id));
create policy notification_read on public.notifications for select to authenticated using(user_id=auth.uid());
grant update(read_at) on public.notifications to authenticated;
create policy notification_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy plan_read on public.plans for select to authenticated using(true);
grant insert,update on public.plans,public.subscriptions,public.platform_settings to authenticated;
create policy plan_manage on public.plans for all to authenticated using(public.is_system()) with check(public.is_system());
create policy subscription_read on public.subscriptions for select to authenticated using(public.admin_of(society_id));
create policy subscription_manage on public.subscriptions for all to authenticated using(public.is_system()) with check(public.is_system());
create policy settings_manage on public.platform_settings for all to authenticated using(public.is_system()) with check(public.is_system());
create policy audit_read on public.audit_logs for select to authenticated using(public.is_system());
create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$ declare j jsonb; begin j=to_jsonb(new); insert into public.audit_logs(actor_id,society_id,action,entity_type,entity_id,details) values(auth.uid(),case when j ? 'society_id' then (j->>'society_id')::uuid else null end,TG_OP,TG_TABLE_NAME,coalesce(j->>'id',j->>'key'),'{}'); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','societies','role_assignments','registration_requests','buildings','memberships','installations','devices','readings','allocation_rules','tariffs','emission_factors','allocation_batches','allocations','credit_transactions','plans','subscriptions','platform_settings','community_challenges'] loop execute format('create trigger audit_mutation after insert or update on public.%I for each row execute function public.audit_change()',t); end loop; end $$;
create function public.limit_operation(op text, maximum integer) returns void language plpgsql security definer set search_path='' as $$ declare n integer; begin if auth.uid() is null then raise exception 'Authentication required'; end if; insert into public.rate_limits values(auth.uid(),op,date_trunc('minute',now()),1) on conflict(actor_id,operation,bucket) do update set count=public.rate_limits.count+1 returning count into n; if n>maximum then raise exception 'Rate limit exceeded'; end if; delete from public.rate_limits where bucket<now()-interval '1 day'; end $$;
create function public.review_registration(request_id uuid, approve boolean, note text) returns uuid language plpgsql security definer set search_path='' as $$ declare r public.registration_requests; s uuid; begin if not public.is_system() then raise exception 'Forbidden'; end if; perform public.limit_operation('review',20); if note is null or length(trim(note))<10 or length(note)>2000 then raise exception 'Document evidence verification and authority in review note'; end if; select * into r from public.registration_requests where id=request_id for update; if not found or r.status<>'pending' then raise exception 'Request is not pending'; end if; if approve then insert into public.societies(name,address) values(r.society_name,r.address) returning id into s; insert into public.role_assignments(user_id,role,society_id) values(r.applicant_id,'society',s); insert into public.allocation_rules(society_id) values(s); end if; update public.registration_requests set status=case when approve then 'approved' else 'rejected' end,reviewed_by=auth.uid(),review_note=note,society_id=s,reviewed_at=now() where id=request_id; insert into public.notifications(user_id,title,body) values(r.applicant_id,'Society application reviewed',case when approve then 'Approved' else 'Rejected' end||': '||note); return s; end $$;
create function public.add_member(society uuid, building uuid, resident uuid, home text) returns uuid language plpgsql security definer set search_path='' as $$ declare m uuid; cap integer; begin if not public.admin_of(society) then raise exception 'Forbidden'; end if; perform public.limit_operation('membership',20); perform 1 from public.societies where id=society for update; select p.max_residents into cap from public.subscriptions s join public.plans p on p.id=s.plan_id where s.society_id=society and s.status='active' and s.starts_at<=now() and (s.ends_at is null or s.ends_at>now()) and p.active; if cap is null then raise exception 'Active subscription required'; end if; if (select count(*) from public.memberships where society_id=society and active)>=cap then raise exception 'Plan resident limit reached'; end if; insert into public.memberships(society_id,building_id,user_id,unit) values(society,building,resident,home) returning id into m; insert into public.role_assignments(user_id,role,society_id) values(resident,'resident',society) on conflict do nothing; insert into public.notifications(user_id,society_id,title,body) values(resident,society,'Society membership activated','Your home has been linked to this society.'); return m; end $$;
create function public.ingest_reading(device uuid, start_at timestamptz, end_at timestamptz, kwh numeric, provenance text, external_id text, correction text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare d public.devices; r public.readings; rid uuid; begin select * into d from public.devices where id=device and active; if not found or not public.admin_of(d.society_id) then raise exception 'Forbidden'; end if; perform public.limit_operation('ingest',120); perform pg_advisory_xact_lock(hashtextextended(d.society_id::text,0)); if start_at is null or end_at is null or end_at>now() or start_at<now()-interval '2 years' or kwh is null or kwh<0 or kwh>1000000 or end_at<=start_at or end_at>start_at+interval '1 day' then raise exception 'Invalid energy interval'; end if; if exists(select 1 from public.allocation_batches where society_id=d.society_id and interval_start<end_at and interval_end>start_at) then raise exception 'Allocated intervals are immutable; contact finance for a reviewed adjustment'; end if; if exists(select 1 from public.readings where device_id=device and interval_start<end_at and interval_end>start_at and not(interval_start=start_at and interval_end=end_at)) then raise exception 'Overlapping interval'; end if; select * into r from public.readings where device_id=device and interval_start=start_at and interval_end=end_at for update; if found then if correction is null then if r.energy_kwh=kwh and r.source_record_id=external_id then return r.id; end if; raise exception 'Duplicate reading requires explicit correction'; end if; if external_id is distinct from r.source_record_id or provenance is distinct from r.source then raise exception 'Correction must retain the original source identity'; end if; if length(trim(correction))<10 or length(correction)>2000 then raise exception 'Correction reason too short'; end if; insert into public.reading_revisions(reading_id,previous_value,new_value,reason,actor_id) values(r.id,r.energy_kwh,kwh,correction,auth.uid()); update public.readings set energy_kwh=kwh,revision=revision+1,correction_reason=correction,received_at=now(),received_by=auth.uid() where id=r.id; return r.id; end if; insert into public.readings(society_id,device_id,interval_start,interval_end,energy_kwh,source,source_record_id,received_by) values(d.society_id,device,start_at,end_at,kwh,provenance,external_id,auth.uid()) returning id into rid; return rid; end $$;
create function public.process_allocation(society uuid,start_at timestamptz,end_at timestamptz) returns uuid language plpgsql security definer set search_path='' as $$ declare g numeric; demand numeric; available numeric; total numeric:=0; b uuid; rule uuid; tid uuid; fid uuid; rate numeric; factor numeric; row record; amount numeric; aid uuid; begin if not public.admin_of(society) then raise exception 'Forbidden'; end if; perform public.limit_operation('allocate',15); perform pg_advisory_xact_lock(hashtextextended(society::text,0)); if start_at is null or end_at is null or end_at>now() or end_at<=start_at or end_at>start_at+interval '1 day' then raise exception 'Invalid interval'; end if; select id into b from public.allocation_batches where society_id=society and interval_start=start_at and interval_end=end_at; if found then return b; end if; if exists(select 1 from public.allocation_batches where society_id=society and interval_start<end_at and interval_end>start_at) then raise exception 'Overlapping allocation'; end if;
-- Require exactly matching, validated readings for every active meter. No prorating or made-up demand.
if not exists(select 1 from public.devices where society_id=society and active and kind='generation') or not exists(select 1 from public.devices where society_id=society and active and kind='consumption') then raise exception 'Generation and consumption meters required'; end if;
if exists(select 1 from public.devices d where d.society_id=society and d.active and not exists(select 1 from public.readings r where r.device_id=d.id and r.interval_start=start_at and r.interval_end=end_at)) then raise exception 'Missing aligned meter readings'; end if;
if exists(select 1 from public.memberships m where m.society_id=society and m.active and not exists(select 1 from public.devices d where d.membership_id=m.id and d.active)) then raise exception 'Every eligible resident requires a consumption meter'; end if;
select coalesce(sum(r.energy_kwh) filter(where d.kind='generation'),0),coalesce(sum(r.energy_kwh) filter(where d.kind='consumption' and m.active),0) into g,demand from public.readings r join public.devices d on d.id=r.device_id left join public.memberships m on m.id=d.membership_id where d.society_id=society and d.active and r.interval_start=start_at and r.interval_end=end_at;
if demand<=0 then raise exception 'No eligible demand'; end if; available=least(g,demand); select id into rule from public.allocation_rules where society_id=society; if rule is null then raise exception 'Configure allocation rule'; end if;
if (select count(*) from public.tariffs where society_id=society and valid_from<=start_at and valid_until>=end_at)>1 or (select count(*) from public.emission_factors where society_id=society and valid_from<=start_at and valid_until>=end_at)>1 then raise exception 'Ambiguous overlapping financial factors'; end if;
select id,inr_per_kwh into tid,rate from public.tariffs where society_id=society and valid_from<=start_at and valid_until>=end_at;
select id,kg_co2e_per_kwh into fid,factor from public.emission_factors where society_id=society and valid_from<=start_at and valid_until>=end_at;
insert into public.allocation_batches(society_id,interval_start,interval_end,generation_kwh,demand_kwh,allocated_kwh,rule_id,tariff_id,factor_id,actor_id) values(society,start_at,end_at,g,demand,0,rule,tid,fid,auth.uid()) returning id into b;
for row in select m.id,m.user_id,r.energy_kwh from public.memberships m join public.devices d on d.membership_id=m.id and d.active join public.readings r on r.device_id=d.id where m.society_id=society and m.active and r.interval_start=start_at and r.interval_end=end_at loop amount=trunc(available*row.energy_kwh/demand,6); total=total+amount; insert into public.allocations(society_id,batch_id,membership_id,energy_kwh,estimated_savings_inr,estimated_avoided_kg) values(society,b,row.id,amount,amount*rate,amount*factor) returning id into aid; insert into public.credit_transactions(society_id,membership_id,allocation_id,amount_kwh) values(society,row.id,aid,amount); insert into public.notifications(user_id,society_id,title,body) values(row.user_id,society,'Solar credit received',amount::text||' kWh allocated from operator-validated interval records. Savings and emissions are estimates.'); end loop;
update public.allocation_batches set allocated_kwh=total where id=b; return b; end $$;
-- Revoke default PUBLIC function execution, explicitly expose only safe entrypoints.
revoke execute on function public.is_system(),public.admin_of(uuid),public.member_of(uuid),public.owns_membership(uuid),public.new_user(),public.audit_change(),public.limit_operation(text,integer),public.review_registration(uuid,boolean,text),public.add_member(uuid,uuid,uuid,text),public.ingest_reading(uuid,timestamptz,timestamptz,numeric,text,text,text),public.process_allocation(uuid,timestamptz,timestamptz) from public,anon,authenticated;
grant execute on function public.is_system(),public.admin_of(uuid),public.member_of(uuid),public.owns_membership(uuid) to authenticated;
grant execute on function public.review_registration(uuid,boolean,text),public.add_member(uuid,uuid,uuid,text),public.ingest_reading(uuid,timestamptz,timestamptz,numeric,text,text,text),public.process_allocation(uuid,timestamptz,timestamptz) to authenticated;
-- Realtime is used only for per-user notifications; RLS still filters delivery.
alter publication supabase_realtime add table public.notifications;
